/**
 * The Grug Hand typeface as stroke data, and the math that sizes one glyph.
 *
 * How grug draws text (and how we copy it): a letter is not an outline, it is
 * the path a pen took. Each glyph is a list of strokes, each stroke a list of
 * points on a 400 x 533 canvas, recorded in the order they were drawn. To
 * animate, you draw the path from the start up to some length. To render a
 * finished letter, you draw the whole path. There is no font file involved.
 *
 * `grug-hand.json` is generated by `scripts/build-typeface.mjs` from the
 * HandDrawnFont package by Jip van der Velde and Michel Elings (Ocho), the
 * makers of grug. Points are integers on a 0..1000 grid to keep the file small.
 *
 * Coordinate spaces, from the inside out:
 *   grid     0..1000 integers in the JSON
 *   canvas   400 x 533.33 "pen units"; animation speed is measured here
 *   glyph    pixels inside the glyph's own box: width = ink width, height = 1.2 x size
 *   text     glyph boxes placed on lines (see plan.ts)
 */
import data from './grug-hand.json';

interface RawGlyph {
  /** The character, lowercase. */
  k: string;
  /** Variation index: most letters were drawn several times so repeats don't look stamped. */
  v: number;
  /** Ink bounds on the grid: x, y, width, height. */
  b: [number, number, number, number];
  /** Baseline and x-height on the grid, as absolute vertical positions. */
  bl: number;
  xh: number;
  /** Strokes, each a flat list: x0, y0, x1, y1, ... */
  s: number[][];
}

interface TypefaceData {
  grid: number;
  canvas: [number, number];
  glyphs: RawGlyph[];
}

const typeface = data as unknown as TypefaceData;
const [CANVAS_WIDTH, CANVAS_HEIGHT] = typeface.canvas;
const GRID = typeface.grid;

const byKey = new Map<string, RawGlyph[]>();
for (const glyph of typeface.glyphs) {
  const list = byKey.get(glyph.k) ?? [];
  list.push(glyph);
  byKey.set(glyph.k, list);
}

/** All drawings of one character. Uppercase maps to the lowercase drawing, as in grug. */
export function variationsFor(character: string): RawGlyph[] {
  return byKey.get(character.toLowerCase()) ?? [];
}

/** Picks a variation. With a seed the choice is stable across renders, so a replay draws the same letters. */
export function pickVariation(variations: RawGlyph[], characterIndex: number, seed: number): RawGlyph {
  // FNV-1a over the character index and the key, same recipe as the Swift package.
  let hash = (seed ^ characterIndex) >>> 0;
  const key = variations[0].k;
  for (let i = 0; i < key.length; i += 1) {
    hash = Math.imul(hash ^ key.charCodeAt(i), 16777619) >>> 0;
  }
  return variations[hash % variations.length];
}

/** One stroke, sized for a target glyph height. Points are in glyph pixels. */
export interface ScaledStroke {
  points: number[]; // x0, y0, x1, y1, ...
  length: number; // in glyph pixels
}

export interface ScaledGlyph {
  /** Width of the ink, in pixels. The box is this wide. */
  width: number;
  /** Always 1.2 x size: room for ascenders above and descenders below the baseline at 0.7 x size. */
  height: number;
  strokes: ScaledStroke[];
  /** Sum of stroke lengths in glyph pixels. */
  totalLength: number;
  /** Sum of stroke lengths in canvas units. Animation speed is "canvas units per second". */
  canvasLength: number;
}

const cache = new Map<string, ScaledGlyph>();

/**
 * Sizes a glyph so that its x-height (baseline to the top of an "x") is 40% of
 * `size`, with the baseline sitting at 70% of `size` from the top of the box.
 * Those two ratios are the whole secret to grug's letters lining up: every
 * glyph was drawn against the same guides, so scaling by x-height puts them
 * all on one line regardless of how tall each drawing is.
 */
export function scaleGlyph(glyph: RawGlyph, size: number): ScaledGlyph {
  const cacheKey = `${glyph.k}/${glyph.v}@${size}`;
  const hit = cache.get(cacheKey);
  if (hit) return hit;

  const toCanvasX = CANVAS_WIDTH / GRID;
  const toCanvasY = CANVAS_HEIGHT / GRID;
  const xHeightUnits = (glyph.bl - glyph.xh) * toCanvasY;
  // The Swift package falls back to fitting the bounds when a glyph has no usable guides.
  const scale = xHeightUnits > 10 ? (size * 0.4) / xHeightUnits : size / Math.max(1, glyph.b[3] * toCanvasY);

  const boundsX = glyph.b[0] * toCanvasX;
  const baselineY = glyph.bl * toCanvasY;
  const baselineInBox = size * 0.7;

  let totalLength = 0;
  let canvasLength = 0;
  const strokes: ScaledStroke[] = glyph.s.map((flat) => {
    const points: number[] = new Array(flat.length);
    let length = 0;
    for (let i = 0; i < flat.length; i += 2) {
      const cx = flat[i] * toCanvasX;
      const cy = flat[i + 1] * toCanvasY;
      const x = (cx - boundsX) * scale;
      const y = baselineInBox + (cy - baselineY) * scale;
      points[i] = x;
      points[i + 1] = y;
      if (i > 0) length += Math.hypot(x - points[i - 2], y - points[i - 1]);
    }
    totalLength += length;
    canvasLength += length / scale;
    return { points, length };
  });

  const scaled: ScaledGlyph = {
    width: glyph.b[2] * toCanvasX * scale,
    height: size * 1.2,
    strokes,
    totalLength,
    canvasLength,
  };
  cache.set(cacheKey, scaled);
  return scaled;
}
